using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 no longer synthesizes index definitions
            // for Cosmos DB (indexes are managed via container indexing policy).
            // Removed: entity.HasIndex(b => b.Name);

            // Breaking change 2: EF 9 uses "id" with just the key value (e.g. "1")
            // instead of "Discriminator|Key" (e.g. "Blog|1"). Opt in to the legacy
            // format so existing documents remain readable.
            entity.HasPartitionKey(b => b.Id);
            entity.UsePropertyAccessMode(PropertyAccessMode.Property);
        });

        // Breaking change 2 (continued): Restore the EF 8 id format "Blog|1"
        // so existing documents are found by their current id values.
        modelBuilder.Entity<Blog>()
            .Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyIdValueGenerator>();

        // Breaking change 3: EF 9 renamed the discriminator property from
        // "Discriminator" to "$type". Existing documents store "Discriminator",
        // so we must keep the old JSON property name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

}

